        "lineGrouped",
        "lineWithKpiTabs",
        "lineComparison",
        "lineComparisonWithKpiTabs",
        "area",
        "barLine",
        "pie",
        "donut",
        "donutLabel",
        "scatter",
        "bubble",
        "kpi",
        "kpiComparison",
        "table",
